TLM.base({"years":{"from":2026,"to":2036},"pope":{"name":"Lav XIV.","date":"05-18"},"ordo":{"prayers":{"Pater noster":[{"k":"text","la":"Pater noster, qui es in cælis, sanctificétur nomen tuum: advéniat regnum tuum: fiat volúntas tua, sicut in cælo et in terra. Panem nostrum cotidiánum da nobis hódie: et dimítte nobis débita nostra, sicut et nos dimíttimus debitóribus nostris: et ne nos indúcas in tentatiónem: sed líbera nos a malo. Amen."}],"Ave Maria":[{"k":"text","la":"Ave María, grátia plena; Dóminus tecum: benedícta tu in muliéribus, et benedíctus fructus ventris tui Jesus. Sancta María, Mater Dei, ora pro nobis peccatóribus, nunc et in hora mortis nostræ. Amen."}],"Credo":[{"k":"text","la":"Credo in Deum, Patrem omnipoténtem, Creatórem cæli et terræ."},{"k":"text","la":"Et in Jesum Christum, Fílium ejus únicum, Dóminum nostrum: qui concéptus est de Spíritu Sancto, natus ex María Vírgine, passus sub Póntio Piláto, crucifíxus, mórtuus, et sepúltus: descéndit ad ínferos; tértia die resurréxit a mórtuis; ascéndit ad cælos; sedet ad déxteram Dei Patris omnipoténtis: inde ventúrus est judicáre vivos et mórtuos."},{"k":"text","la":"Credo in Spíritum Sanctum, sanctam Ecclésiam cathólicam, Sanctórum communiónem, remissiónem peccatórum, carnis resurrectiónem, vitam ætérnam. Amen."}],"Gloria":[{"k":"text","la":"Glória Patri, et Fílio, et Spirítui Sancto.","mark":"V"},{"k":"text","la":"Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.","mark":"R"}],"Gloria1":[{"k":"text","la":"Glória Patri, et Fílio, * et Spirítui Sancto.","mark":"V"}],"Requiem":[{"k":"text","la":"Réquiem ætérnam dona eis, Dómine.","mark":"V"},{"k":"text","la":"Et lux perpétua lúceat eis.","mark":"R"}],"Alleluia":[{"k":"text","la":"Allelúja."},{"k":"text","la":"Laus tibi, Dómine, Rex ætérnæ glóriæ."}],"Dominus":[{"k":"text","la":"Dóminus vobíscum.","mark":"V"},{"k":"text","la":"Et cum spíritu tuo.","mark":"R"},{"k":"text","la":"Dómine, exáudi oratiónem meam.","mark":"V"},{"k":"text","la":"Et clamor meus ad te véniat.","mark":"R"},{"k":"rubric","la":"omittitur secunda Domine, exaudi"}],"Flectamus":[{"k":"text","la":"Flectámus génua.","mark":"V"},{"k":"text","la":"Leváte.","mark":"R"}],"Dominus vobiscum":[{"k":"text","la":"Dóminus vobíscum.","mark":"V"},{"k":"text","la":"Et cum spíritu tuo.","mark":"R"}],"IteMissa":[{"k":"text","la":"Ite, Missa est.","mark":"V"},{"k":"text","la":"Deo grátias.","mark":"R"},{"k":"text","la":"Ite, Missa est, allelúja, allelúja.","mark":"V"},{"k":"text","la":"Deo grátias, allelúja, allelúja.","mark":"R"},{"k":"text","la":"Benedicámus Dómino.","mark":"V"},{"k":"text","la":"Deo grátias.","mark":"R"},{"k":"text","la":"Requiéscant in pace.","mark":"V"},{"k":"text","la":"Amen.","mark":"R"}],"Confiteor":[{"k":"text","la":"Confíteor Deo omnipoténti, beátæ Maríæ semper Vírgini, beáto Michaéli Archángelo, beáto Joánni Baptístæ, sanctis Apóstolis Petro et Paulo, et ómnibus Sanctis, quia peccávi nimis, cogitatióne, verbo et ópere: /:percutit sibi pectus:/ mea culpa, mea culpa, mea máxima culpa. Ídeo precor beátam Maríam semper Vírginem, beátum Michaélem Archángelum, beátum Joánnem Baptístam, sanctos Apóstolos Petrum et Paulum, et omnes Sanctos, oráre pro me ad Dóminum Deum nostrum."}],"Misereatur":[{"k":"text","la":"Misereátur nostri omnípotens Deus, et dimíssis peccátis nostris, perdúcat nos ad vitam ætérnam. Amen."}],"Indulgentiam":[{"k":"text","la":"Indulgéntiam, + absolutiónem et remissiónem peccatórum nostrórum tríbuat nobis omnípotens et miséricors Dóminus. Amen."}],"Domine labia":[{"k":"text","la":"Dómine, lábia ✠ mea apéries.","mark":"V"},{"k":"text","la":"Et os meum annuntiábit laudem tuam.","mark":"R"}],"Deus in adjutorium":[{"k":"text","la":"Deus + in adjutórium meum inténde.","mark":"V"},{"k":"text","la":"Dómine, ad adjuvándum me festína.","mark":"R"}],"Tu autem":[{"k":"text","la":"Tu autem, Dómine, miserére nobis.","mark":"V"},{"k":"text","la":"Deo grátias.","mark":"R"}],"Benedicamus Domino":[{"k":"text","la":"Benedicámus Dómino.","mark":"V"},{"k":"text","la":"Deo grátias.","mark":"R"}],"Benedicamus Domino1":[{"k":"text","la":"Benedicámus Dómino, allelúja, allelúja.","mark":"V"},{"k":"text","la":"Deo grátias, allelúja, allelúja.","mark":"R"}],"Deo gratias":[{"k":"text","la":"Deo grátias.","mark":"R"}],"Gloria tibi":[{"k":"text","la":"Glória tibi, Dómine.","mark":"R"}],"Laus tibi":[{"k":"text","la":"Laus tibi, Christe.","mark":"R"},{"k":"text","la":"Per Evangélica dicta, deleántur nostra delícta.","mark":"S"}],"Fidelium animae":[{"k":"text","la":"Fidélium ánimæ per misericórdiam Dei requiéscant in pace.","mark":"V"},{"k":"text","la":"Amen.","mark":"R"}],"Per Dominum":[{"k":"text","la":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum."},{"k":"text","la":"Amen.","mark":"R"}],"Per Dominum eiusdem":[{"k":"text","la":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte ejúsdem Spíritus Sancti Deus, per ómnia sǽcula sæculórum."},{"k":"text","la":"Amen.","mark":"R"}],"Qui cum Patre":[{"k":"text","la":"Qui cum Pátre et Spíritu Sancto vivis et regnas Deus per ómnia sǽcula sæculórum."},{"k":"text","la":"Amen.","mark":"R"}],"Per eumdem":[{"k":"text","la":"Per eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum."},{"k":"text","la":"Amen.","mark":"R"}],"Per eundem":[{"k":"text","la":"Per eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum."},{"k":"text","la":"Amen.","mark":"R"}],"Qui vivis":[{"k":"text","la":"Qui vivis et regnas cum Deo Patre, in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum."},{"k":"text","la":"Amen.","mark":"R"}],"Qui tecum":[{"k":"text","la":"Qui tecum vivit et regnat in unitáte Spíritus Sancti Deus per ómnia sǽcula sæculórum."},{"k":"text","la":"Amen.","mark":"R"}],"Qui tecum eiusdem":[{"k":"text","la":"Qui tecum vivit et regnat in unitáte ejúsdem Spíritus Sancti Deus per ómnia sǽcula sæculórum."},{"k":"text","la":"Amen.","mark":"R"}],"Te Deum":[{"k":"text","la":"Te Deum laudámus: * te Dóminum confitémur."},{"k":"text","la":"Te ætérnum Patrem * omnis terra venerátur."},{"k":"text","la":"Tibi omnes Ángeli, * tibi Cæli, et univérsæ Potestátes:"},{"k":"text","la":"Tibi Chérubim et Séraphim * incessábili voce proclámant:"},{"k":"sep"},{"k":"text","la":"/:(Fit reverentia):/ Sanctus, Sanctus, Sanctus * Dóminus Deus Sábaoth."},{"k":"sep"},{"k":"text","la":"Pleni sunt cæli et terra * majestátis glóriæ tuæ."},{"k":"text","la":"Te gloriósus * Apostolórum chorus,"},{"k":"text","la":"Te Prophetárum * laudábilis númerus,"},{"k":"text","la":"Te Mártyrum candidátus * laudat exércitus."},{"k":"text","la":"Te per orbem terrárum * sancta confitétur Ecclésia,"},{"k":"text","la":"Patrem * imménsæ majestátis;"},{"k":"text","la":"Venerándum tuum verum * et únicum Fílium;"},{"k":"text","la":"Sanctum quoque * Paráclitum Spíritum."},{"k":"text","la":"Tu Rex glóriæ, * Christe."},{"k":"text","la":"Tu Patris * sempitérnus es Fílius."},{"k":"sep"},{"k":"rubric","la":"Fit reverentia"},{"k":"text","la":"Tu, ad liberándum susceptúrus hóminem: * non horruísti Vírginis uterum."},{"k":"sep"},{"k":"text","la":"Tu, devícto mortis acúleo, * aperuísti credéntibus regna cælórum."},{"k":"text","la":"Tu ad déxteram Dei sedes, * in glória Patris."},{"k":"text","la":"Judex créderis * esse ventúrus."},{"k":"sep"},{"k":"rubric","la":"Sequens versus dicitur flexis genibus"},{"k":"text","la":"Te ergo quǽsumus, tuis fámulis súbveni, * quos pretióso sánguine redemísti."},{"k":"sep"},{"k":"text","la":"Ætérna fac cum Sanctis tuis * in glória numerári."},{"k":"text","la":"Salvum fac pópulum tuum, Dómine, * et bénedic hereditáti tuæ."},{"k":"text","la":"Et rege eos, * et extólle illos usque in ætérnum."},{"k":"text","la":"Per síngulos dies * benedícimus te."},{"k":"sep"},{"k":"rubric","la":"Fit reverentia, secundum consuetudinem"},{"k":"text","la":"Et laudámus nomen tuum in sǽculum, * et in sǽculum sǽculi."},{"k":"sep"},{"k":"text","la":"Dignáre, Dómine, die isto * sine peccáto nos custodíre."},{"k":"text","la":"Miserére nostri, Dómine, * miserére nostri."},{"k":"text","la":"Fiat misericórdia tua, Dómine, super nos, * quemádmodum sperávimus in te."},{"k":"text","la":"In te, Dómine, sperávi: * non confúndar in ætérnum."}],"Ante":[{"k":"text","la":"/:flexis genibus:/"},{"k":"text","la":"Aperi Dómine, os meum ad benedicéndum nomen sanctum tuum: munda quoque cor meum ab ómnibus vanis, pervérsis et aliénis cogitatiónibus; intelléctum illúmina, afféctum inflámma, ut digne, atténte ac devóte hoc Offícium recitáre váleam, et exaudíri mérear ante conspéctum divínæ Majestátis túæ. Per Christum Dóminum nostrum."},{"k":"text","la":"Amen.","mark":"R"},{"k":"text","la":"Dómine, in unióne illíus divínæ intentiónis, qua ipse in terris laudes Deo persolvísti, has tibi Horas (vel hanc tibi Horam) persólvo."}],"Post":[{"k":"text","la":"Sacrosánctæ et indivíduæ Trinitáti, crucifíxi Dómini nostri Jesu Christi humanitáti, beatíssimæ et gloriosíssimæ sempérque Vírginis Maríæ fœcúndæ integritáti, et ómnium Sanctórum universitáti sit sempitérna laus, honor, virtus et glória ab omni creatúra, nobísque remíssio ómnium peccatórum, per infiníta sǽcula sæculórum."},{"k":"text","la":"Amen.","mark":"R"},{"k":"sep"},{"k":"text","la":"Beáta víscera Maríæ Vírginis, quæ portavérunt ætérni Pátris Fílium.","mark":"V"},{"k":"text","la":"Et beáta úbera, quæ lactavérunt Christum Dóminum.","mark":"R"},{"k":"sep"},{"k":"text","la":"Pater noster."},{"k":"text","la":"Ave Maria."}],"Conclmart":[{"k":"text","la":"Et álibi aliórum plurimórum sanctórum Mártyrum et Confessórum, atque sanctárum Vírginum.","mark":"V"},{"k":"macro","name":"Deo gratias"}],"DefunctV":[{"k":"macro","name":"Dominus_vobiscum"},{"k":"macro","name":"Benedicamus_Domino"},{"k":"rubric","la":"%Vespera defunctorum% recitata est, omittuntur Pater, Ave"},{"k":"macro","name":"Fidelium animae"},{"k":"macro","name":"Pater noster"}],"DefunctM":[{"k":"rubric","la":"%Officium defunctorum% recitatum est"}],"Oremus":[{"k":"text","la":"Orémus."}],"Papa":[{"k":"rubric","la":"Pro Papa"}],"Te decet":[{"k":"text","la":"Te decet laus, + te decet hymnus: tibi glória Deo Patri, et Fílio, cum Spíritu Sancto in sǽcula sæculórum. Amen."}],"MLitany":[{"k":"text","la":"Kyrie eléison. Christe, eléison. Kyrie, eléison."},{"k":"macro","name":"pater_noster"}],"Vidi aquam":[{"k":"head","la":"Vidi aquam"},{"k":"text","la":"Ant. Vidi aquam egrediéntem de templo a látere dextro, allelúja: et omnes ad quos pervénit aqua ista salvi facti sunt et dicent: allelúja, allelúja. _"},{"k":"text","la":"Ps. Confitémini Dómino, quoniam bonus: quoniam in sǽculum misericórdia eius."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Ant. Vidi aquam egrediéntem de templo a látere dextro, allelúja: et omnes ad quos pervénit aqua ista salvi facti sunt et dicent: allelúja, allelúja. _"},{"k":"sep"},{"k":"text","la":"Osténde nobis, Dómine, misericórdiam tuam, allelúja.","mark":"V"},{"k":"text","la":"Et salutáre tuum da nobis, allelúja.","mark":"R"},{"k":"text","la":"Dómine, exáudi oratiónem meam.","mark":"V"},{"k":"text","la":"Et clamor meus ad te véniat.","mark":"R"},{"k":"text","la":"Dóminus vobíscum.","mark":"V"},{"k":"text","la":"Et cum spíritu tuo.","mark":"R"},{"k":"sep"},{"k":"text","la":"Orémus."},{"k":"text","la":"Exáudi nos, Dómine sancte, Pater omnípotens, ætérne Deus, et míttere dignéris sanctum Angelum tuum de cælis, qui custódiat, fóveat, prótegat, vísitet atque deféndat omnes habitántes in hoc habitáculo. Per Christum Dóminum nostrum. Amen."}],"Asperges me":[{"k":"head","la":"Asperges me"},{"k":"text","la":"Ant. Aspérges me, Dómine, hyssópo, et mundábor: lavábis me, et super nivem dealbábor."},{"k":"text","la":"Ps. Miserére mei, Deus, secúndum magnam misericórdiam tuam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Ant. Aspérges me, Dómine, hyssópo, et mundábor: lavábis me, et super nivem dealbábor."},{"k":"sep"},{"k":"text","la":"Osténde nobis, Dómine, misericórdiam tuam.","mark":"V"},{"k":"text","la":"Et salutáre tuum da nobis.","mark":"R"},{"k":"text","la":"Dómine, exáudi oratiónem meam.","mark":"V"},{"k":"text","la":"Et clamor meus ad te véniat.","mark":"R"},{"k":"text","la":"Dóminus vobíscum.","mark":"V"},{"k":"text","la":"Et cum spíritu tuo.","mark":"R"},{"k":"sep"},{"k":"text","la":"Orémus."},{"k":"text","la":"Exáudi nos, Dómine sancte, Pater omnípotens, ætérne Deus, et míttere dignéris sanctum Angelum tuum de cælis, qui custódiat, fóveat, prótegat, vísitet atque deféndat omnes habitántes in hoc habitáculo. Per Christum Dóminum nostrum. Amen."}],"Ultima Evangelium":[{"k":"text","la":"Inítium ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joann. 1, 1-14"},{"k":"rubric","la":"Junctis manibus prosequitur:"},{"k":"text","la":"In princípio erat Verbum, et Verbum erat apud Deum, et Deus erat Verbum. Hoc erat in princípio apud Deum. Omnia per ipsum facta sunt: et sine ipso factum est nihil, quod factum est: in ipso vita erat, et vita erat lux hóminum: et lux in ténebris lucet, et ténebræ eam non comprehendérunt."},{"k":"text","la":"Fuit homo missus a Deo, cui nomen erat Joánnes. Hic venit in testimónium, ut testimónium perhibéret de lúmine, ut omnes créderent per illum. Non erat ille lux, sed ut testimónium perhibéret de lúmine."},{"k":"text","la":"Erat lux vera, quæ illúminat omnem hóminem veniéntem in hunc mundum. In mundo erat, et mundus per ipsum factus est, et mundus eum non cognóvit. In própria venit, et sui eum non recepérunt. Quotquot autem recepérunt eum, dedit eis potestátem fílios Dei fíeri, his, qui credunt in nómine ejus: qui non ex sanguínibus, neque ex voluntáte carnis, neque ex voluntáte viri, sed ex Deo nati sunt. (Genuflectit dicens:) Et Verbum caro factum est, (Et surgens prosequitur:) et habitávit in nobis: et vídimus glóriam ejus, glóriam quasi Unigéniti a Patre, plenum grátiæ et veritátis."}]},"prefaces":{"Adv":[{"k":"rubric","la":"de Adventu"},{"k":"text","la":"Vere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine, sancte Pater, omnípotens ætérne Deus: per Christum Dóminum nostrum. Quem pérdito hóminum géneri Salvatórem miséricors et fidélis promisísti: cujus véritas instrúeret ínscios, sánctitas justificáret ímpios, virtus adiuváret infírmos. Dum ergo prope est ut véniat quem missúrus es, et dies affúlget liberatiónis nostræ, in hac promissiónum tuárum fide, piis gáudiis exsultámus. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus, cumque omni milítia cœléstis exércitus, hymnum glóriæ tuæ cánimus, sine fine dicéntes:"}],"Nat":[{"k":"rubric","la":"de Nativitate Domini"},{"k":"text","la":"Vere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Quia per incarnáti Verbi mystérium nova mentis nostræ óculis lux tuæ claritátis infúlsit: ut, dum visibíliter Deum cognóscimus, per hunc in invisibílium amorem rapiámur. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus cumque omni milítia cæléstis exércitus hymnum glóriæ tuæ cánimus, sine fine dicéntes."}],"Epi":[{"k":"rubric","la":"de Epiphania Domini"},{"k":"text","la":"Vere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Quia, cum Unigénitus tuus in substántia nostræ mortalitátis appáruit, nova nos immortalitátis suæ luce reparávit. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus cumque omni milítia cœléstis exércitus hymnum glóriæ tuæ cánimus, sine fine dicéntes:"}],"Quad":[{"k":"rubric","la":"de Quadragesima"},{"k":"text","la":"Vere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine, sancte Pater, omnípotens ætérne Deus: Qui corporáli ieiúnio vítia cómprimis, mentem élevas, virtútem largíris et prǽmia: per Christum Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes, ac beáta Séraphim, sócia exsultatióne concélebrant. Cum quibus et nostras voces, ut admítti iúbeas, deprecámur, súpplici confessióne dicéntes:"}],"Sacramento":[{"k":"rubric","la":"de Sanctissimo Sacramento"},{"k":"text","la":"Vere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine, sancte Pater, omnípotens ætérne Deus: per Christum Dóminum nostrum. Qui remótis carnálium victimárum inánibus umbris, Corpus et Sánguinem suum nobis in sacrifícium commendávit: ut in omni loco offerátur nómini tuo, quæ tibi sola complácuit, oblátio munda. In hoc ígitur inscrutábilis sapientiæ, et imménsæ caritátis mystério, idípsum quod semel in Cruce perfécit, non cessat mirabíliter operári, ipse ófferens, ipse et oblátio. Et nos, unam secum hóstiam effectos, ad sacrum ínvitat convívium, in quo ipse cibus noster súmitur, recólitur memória Passiónis ejus, mens implétur grátia, et futúræ glóriæ nobis pignus datur. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus, cumque omni milítia cœléstis exércitus, hymnum glóriæ tuæ cánimus, sine fine dicéntes:"}],"Quad5":[{"k":"rubric","la":"de Sancta Cruce"},{"k":"text","la":"Vere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Qui salútem humáni géneris in ligno Crucis constituísti: ut, unde mors oriebátur, inde vita resúrgeret: et, qui in ligno vincébat, in ligno quoque vincerétur: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti júbeas, deprecámur, súpplici confessióne dicéntes:"}],"Pasch":[{"k":"rubric","la":"Paschalis"},{"k":"text","la":"Vere dignum et justum est, æquum et salutáre: Te quidem, Dómine, omni témpore, sed in hoc potíssimum gloriósius prædicáre, cum Pascha nostrum immolátus est Christus. Ipse enim verus est Agnus, qui ábstulit peccáta mundi. Qui mortem nostram moriéndo destrúxit et vitam resurgéndo reparávit. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus cumque omni milítia cœléstis exércitus hymnum glóriæ tuæ cánimus, sine fine dicéntes:"}],"Asc":[{"k":"rubric","la":"de Ascensione Domini"},{"k":"text","la":"Vere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Qui post resurrectiónem suam ómnibus discípulis suis maniféstus appáruit et, ipsis cernéntibus, est elevátus in cælum, ut nos divinitátis suæ tribúeret esse partícipes. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus cumque omni milítia cœléstis exércitus hymnum glóriæ tuæ cánimus, sine fine dicéntes:"}],"Cord":[{"k":"rubric","la":"de sacratissimo Cordis Jesu"},{"k":"text","la":"Vere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Qui Unigénitum tuum, in Cruce pendéntem, láncea mílitis transfígi voluísti: ut apértum Cor, divínæ largitátis sacrárium, torréntes nobis fúnderet miseratiónis et grátiæ: et, quod amóre nostri flagráre numquam déstitit, piis esset réquies et pœniténtibus pater et salútis refúgium. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus cumque omni milítia cœléstis exércitus hymnum glóriæ tuæ cánimus, sine fine dicéntes:"}],"Regis":[{"k":"rubric","la":"de D.N. Jesu Christi Rege"},{"k":"text","la":"Vere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Qui unigénitum Fílium tuum, Dóminum nostrum Jesum Christum, Sacerdótem ætérnum et universórum Regem, óleo exsultatiónis unxísti: ut, seípsum in ara crucis hóstiam immaculátam et pacíficam ófferens, redemptiónis humánæ sacraménta perágeret: et suo subjéctis império ómnibus creatúris, ætérnum et universále regnum, imménsæ tuæ tráderet Majestáti. Regnum veritátis et vitæ: regnum sanctitátis et grátiæ: regnum justítiæ, amóris et pacis. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus cumque omni milítia cœléstis exércitus hymnum glóriæ tuæ cánimus, sine fine dicéntes:"}],"Spiritu":[{"k":"rubric","la":"de Spiritu Sancto"},{"k":"text","la":"Vere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Qui, ascéndens super omnes cælos sedénsque ad déxteram tuam, promíssum Spíritum Sanctum * * in fílios adoptiónis effúdit. Quaprópter profúsis gáudiis totus in orbe terrárum mundus exsúltat. Sed et supérnæ Virtútes atque angélicæ Potestátes hymnum glóriæ tuæ cóncinunt, sine fine dicéntes:"}],"Trinitate":[{"k":"rubric","la":"de sanctissima Trinitate"},{"k":"text","la":"Vere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Qui cum unigénito Fílio tuo et Spíritu Sancto unus es Deus, unus es Dóminus: non in uníus singularitáte persónæ, sed in uníus Trinitáte substántiæ. Quod enim de tua glória, revelánte te, crédimus, hoc de Fílio tuo, hoc de Spíritu Sancto sine differéntia discretiónis sentímus. Ut in confessióne veræ sempiternǽque Deitátis, et in persónis propríetas, et in esséntia únitas, et in majestáte adorétur æquálitas. Quam laudant Angeli atque Archángeli, Chérubim quoque ac Séraphim: qui non cessant clamáre cotídie, una voce dicéntes:"}],"Maria":[{"k":"rubric","la":"de Beata Maria Virgine"},{"k":"text","la":"Vere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Et te in *Festivitáte* beátæ Maríæ semper Vírginis collaudáre, benedícere et prædicáre. Quæ et Unigénitum tuum Sancti Spíritus obumbratióne concépit: et, virginitátis glória permanénte, lumen ætérnum mundo effúdit, Jesum Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessióne dicéntes:"}],"Joseph":[{"k":"rubric","la":"de S. Joseph"},{"k":"text","la":"Vere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Et te in *Veneratióne* beáti Joseph débitis magnificáre præcóniis, benedícere et prædicáre. Qui et vir justus, a te Deíparæ Vírgini Sponsus est datus: et fidélis servus ac prudens, super Famíliam tuam est constitútus: ut Unigénitum tuum, Sancti Spíritus obumbratióne concéptum, paterna vice custodíret, Jesum Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti júbeas, deprecámur, súpplici confessióne dicéntes:"}],"Apostolis":[{"k":"rubric","la":"de Apostolis"},{"k":"text","la":"Vere dignum et justum est, æquum et salutáre: Te, Dómine, supplíciter exoráre, ut gregem tuum, Pastor ætérne, non déseras: sed per beátos Apóstolos tuos contínua protectióne custódias. Ut iísdem rectóribus gubernétur, quos óperis tui vicários eídem contulísti præésse pastóres. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus cumque omni milítia cœléstis exércitus hymnum glóriæ tuæ cánimus, sine fine dicéntes:"}],"Communis":[{"k":"rubric","la":"Communis"},{"k":"text","la":"Vere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:"}],"Defunctorum":[{"k":"rubric","la":"Defunctorum"},{"k":"text","la":"Vere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. In quo nobis spes beátæ resurrectiónis effúlsit, ut, quos contrístat certa moriéndi condício, eósdem consolétur futúræ immortalitátis promíssio. Tuis enim fidélibus, Dómine, vita mutátur, non tóllitur: et, dissolúta terréstris hujus incolátus domo, ætérna in cælis habitátio comparátur. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus cumque omni milítia cœléstis exércitus hymnum glóriæ tuæ cánimus, sine fine dicéntes:"}],"Sanctis":[{"k":"rubric","la":"de Omnibus Sanctis et Ss. Patronis"},{"k":"text","la":"Vere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine, sancte Pater, omnípotens ætérne Deus: qui glorificáris in concílio Sanctórum, et eórum coronándo mérita, corónas dona tua: qui nobis eórum præbes, et conversatióne exémplum, et communióne consórtium, et intercessióne subsídium: ut tantam habéntes impósitam nubem téstium, per patiéntiam currámus ad propósitum nobis certámen, et cum eis percipiámus immarcescíbilem glóriæ corónam. Per Jesum Christum Dóminum nostrum, cujus sánguine ministrátur nobis intróitus in ætérnum regnum. Per quem majestátem tuam treméntes adórant Angeli, et omnes spírituum cœléstium chori sócia exsultatióne concélebrant. Cum quibus et nostras voces, ut admítti iúbeas, deprecámur, súpplici confessióne dicéntes:"}],"Dedicatio":[{"k":"rubric","la":"in Dedicatione Ecclesiae"},{"k":"text","la":"Vere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine, sancte Pater, omnípotens ætérne Deus: Qui hanc oratiónis domum, quam ædificávimus, bonórum ómnium largítor inhábitas, et Ecclésiam, quam ipse fundásti, incessábili operatióne sanctíficas. Hæc est enim vere domus oratiónis, visibílibus ædifíciis adumbráta, templum habitatiónis glóriæ tuæ, sedes incommutábilis veritátis, sanctuárium ætérnæ caritátis. Hæc est arca, qui nos a mundi eréptos dilúvio, in portu salútis indúcit. Hæc est dilécta et única sponsa, quam acquisívit Christus sánguine suo, quam vivíficat Spíritu suo, cujus in sinu renáti per grátiam tuam, lacte verbi páscimur, pane vitæ roborámur, misericórdiæ tuæ subsídiis confovémur. Hæc fidéliter in terris, Sponso adiuvánte, mílitat, et perénniter in cælis, ipso coronánte, triúmphat. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus, cumque omni milítia cœléstis exércitus, hymnum glóriæ tuæ cánimus, sine fine dicéntes:"}],"Baptista":[{"k":"rubric","la":"de S. Joannis Baptistæ"},{"k":"text","la":"Vere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine, sancte Pater, omnípotens ætérne Deus: Et tuam in beáto Joánne Bapísta Præcursóre magnificéntiam collaudáre, qui vocem Matris Dómini nondum éditus sensit, et adhuc clauso útero, advéntum salútis humánæ prophética exsulatióne significávit. Qui et genetricis sterilitátem concéptus ábstulit, et patris linguam natus absólvit, solúsque ómnium prophetárum Redemptórem mundi, quem prænuntiávit, osténdit. Et ut sacræ purificatiónis efféctum aquárum natúra concíperet, sanctificándis Jordánis fluéntis, ipsum baptísmo baptísmatis lavit auctórem. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus, cumque omni milítia cæléstis exércitus hymnum glóriæ tuæ cántimus, sine fine dicéntes:"}],"Chrismatis":[{"k":"rubric","la":"special"},{"k":"text","la":"Vere dignum et justum est, aequum et salutáre, cleméntiam tuam supplíciter obsecráre, ut spirituális lavácri baptísmo renovándis creatúram chrísmatis in sacraméntum perféctae salútis vitaéque confírmes ; ut sanctificatióne unctiónis infúsa, corruptióne primae nativitátis absórpta, sanctum uniuscujúsque templum acceptábilis vitae innocéntiae odóre redoléscat ; ut secúndum constitutiónis tuae sacraméntum, régio et sacerdotáli propheticóque honóre perfúsi, vestiménto incorrúpti múneris induántur: per Christum Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Caeli, caelorúmque Virtútes, ac beáta Séraphim, sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti júbeas, deprecámur, súpplici confessióne dicéntes:"}],"C-common":[{"k":"text","la":"Communicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed"}],"C-Nat":[{"k":"rubric","la":"In Nativitate Domini et per Octavam dicitur:"},{"k":"text","la":"Communicántes, et diem sacratíssimum celebrántes, quo beátæ Maríæ intemeráta virgínitas huic mundo édidit Salvatórem: sed et memóriam venerántes, in primis ejúsdem gloriósæ semper Vírginis Maríæ, Genetrícis ejúsdem Dei et Dómini nostri Jesu Christi: sed"}],"C-Epi":[{"k":"rubric","la":"In Epiphania Domini et per Octavam dicitur:"},{"k":"text","la":"Communicántes, et diem sacratíssimum celebrántes, quo Unigénitus tuus, in tua tecum glória coætérnus, in veritáte carnis nostræ visibíliter corporális appáruit: sed et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis ejúsdem Dei et Dómini nostri Jesu Christi: sed"}],"C-Pasc":[{"k":"rubric","la":"A Sabbato sancto usque ad Sábbatum in Albis dicitur:"},{"k":"text","la":"Communicántes, et diem sacratíssimum celebrántes Resurrectiónis Dómini nostri Jesu Christi secúndum carnem: sed et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis ejúsdem Dei et Dómini nostri Jesu Christi: sed"}],"C-Asc":[{"k":"rubric","la":"In Ascensione Domini et per Octavam dicitur:"},{"k":"text","la":"Communicántes, et diem sacratíssimum celebrántes, quo Dóminus noster, unigénitus Fílius tuus, unítam sibi fragilitátis nostræ substántiam in glóriæ tuæ déxtera collocávit: sed et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis ejúsdem Dei et Dómini nostri Jesu Christi: sed"}],"C-Pent":[{"k":"rubric","la":"A Vigilia Pentecostes usque ad sequens Sábbatum inclusive dicitur:"},{"k":"text","la":"Communicántes, et diem sacratíssimum Pentecóstes celebrántes, quo Spíritus Sanctus Apóstolis innúmeris linguis appáruit: sed et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed"}],"H-Pent":[{"k":"rubric","la":"A Sabbato sancto usque ad Sabbatum in Albis incl. et a Vigilia Pentecostes usque ad sequens Sabbatum incl. additur:"},{"k":"text","la":"quam tibi offérimus pro his quoque, quos regeneráre dignatus es ex aqua et Spíritu Sancto, tríbuens eis remissiónem omnium peccatórum,"}],"C-common1962":[{"k":"text","la":"Communicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,"}],"C-Nat1962":[{"k":"rubric","la":"In Nativitate Domini et per Octavam dicitur:"},{"k":"text","la":"Communicántes, et diem sacratíssimum celebrántes, quo beátæ Maríæ intemeráta virgínitas huic mundo édidit Salvatórem: sed et memóriam venerántes, in primis ejúsdem gloriósæ semper Vírginis Maríæ, Genetrícis ejúsdem Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,"}],"C-Epi1962":[{"k":"rubric","la":"In Epiphania Domini dicitur:"},{"k":"text","la":"Communicántes, et diem sacratíssimum celebrántes, quo Unigénitus tuus, in tua tecum glória coætérnus, in veritáte carnis nostræ visibíliter corporális appáruit: sed et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis ejúsdem Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,"}],"C-Pasc1962":[{"k":"rubric","la":"A Sabbato sancto usque ad Sábbatum in Albis dicitur:"},{"k":"text","la":"Communicántes, et diem sacratíssimum celebrántes Resurrectiónis Dómini nostri Jesu Christi secúndum carnem: sed et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis ejúsdem Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,"}],"C-Asc1962":[{"k":"rubric","la":"In Ascensione Domini dicitur:"},{"k":"text","la":"Communicántes, et diem sacratíssimum celebrántes, quo Dóminus noster, unigénitus Fílius tuus, unítam sibi fragilitátis nostræ substántiam in glóriæ tuæ déxtera collocávit: sed et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis ejúsdem Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,"}],"C-Pent1962":[{"k":"rubric","la":"A Vigilia Pentecostes usque ad sequens Sábbatum inclusive dicitur:"},{"k":"text","la":"Communicántes, et diem sacratíssimum Pentecóstes celebrántes, quo Spíritus Sanctus Apóstolis innúmeris linguis appáruit: sed et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,"}]}},"gloria":{"la":"Glória in excélsis Deo et in terra pax homínibus bonae voluntátis. Laudámus te, benedícimus te, adorámus te, glorificámus te, grátias ágimus tibi propter magnam glóriam tuam, Dómine Deus, Rex caeléstis, Deus Pater omnípotens. Dómine Fili Unigénite, Iesu Christe, Dómine Deus, Agnus Dei, Fílius Patris, qui tollis peccáta mundi, miserére nobis; qui tollis peccáta mundi, súscipe deprecatiónem nostram. Qui sedes ad déxteram Patris, miserére nobis. Quóniam tu solus Sanctus, tu solus Dóminus, tu solus Altíssimus, Iesu Christe, cum Sancto Spíritu: in glória Dei Patris. Amen.","hr":"Slava Bogu na visini i na zemlji mir ljudima dobre volje. Hvalimo Te, blagoslivljamo Te, klanjamo Ti se, slavimo Te, zahvaljujemo Ti radi velike slave Tvoje. Gospodine Bože, Kralju nebeski, Bože Oče Svemogući. Gospodine Sine jedinorođeni, Isuse Kriste, Gospodine Bože, Jaganjče Božji, Sine Očev, koji oduzimaš grijehe svijeta, smiluj nam se; koji oduzimaš grijehe svijeta, primi našu molitvu. Koji sjediš s desne Ocu, smiluj nam se. Jer Ti si jedini svet. Ti si jedini Gospodin. Ti si jedini Svevišnji, Isuse Kriste, sa Svetim Duhom, u slavi Boga Oca. Amen."},"credo":{"la":"Credo in unum Deum. Patrem omnipoténtem, factórem caeli et terrae, visibílium ómnium et invisibílium. Et in unum Dóminum Iesum Christum, Fílium Dei unigénitum. Et ex Patre natum ante ómnia saécula. Deum de Deo, lumen de lúmine, Deum verum de Deo vero. Génitum, non factum, consubstantiálem Patri: per quem ómnia facta sunt. Qui propter nos hómines et propter nostram salútem descéndit de caelis. (Hic genuflecitur) Et incarnátus est de Spíritu Sancto ex María Vírgine: Et homo factus est. Crucifíxus étiam pro nobis: sub Póntio Piláto passus, et sepúltus est. Et resurréxit tértia die, secúndum Scriptúras. Et ascéndit in caelum: sedet ad déxteram Patris. Et íterum ventúrus est cum glória iudicáre vivos et mórtuos: cuius regni non erit finis. Et in Spíritum Sanctum, Dóminum et vivificántem: qui ex Patre Filióque procédit. Qui cum Patre et Fílio simul adorátur et conglorificátur: qui locútus est per Prophétas. Et unam sanctam cathólicam et apostolicam Ecclésiam. Confíteor unum baptísma in remissiónem peccatórum. Et expécto resurrectiónem mortuórum. Et vitam ventúri saéculi. Amen.","hr":"Vjerujem u jednoga Boga, Oca svemogućega, stvoritelja neba i zemlje, svega vidljivoga i nevidljivoga.I u jednoga Gospodina Isusa Krista, jedinorođenoga Sina Božjega. Rođenog od Oca prije svih vjekova. Boga od Boga, svjetlo od svjetla, pravoga Boga od pravoga Boga. Rođena, ne stvorena, istobitna s Ocem, po kome je sve stvoreno. Koji je radi nas ljudi i radi našega spasenja sišao s nebesa. (ovdje se poklekne) I utjelovio se po Duhu Svetom od Marije Djevice: i postao čovjekom. Raspet također za nas: pod Poncijem Pilatom mučen i pokopan. I uskrsnuo treći dan, po Svetom Pismu. I uzašao na nebo: sjedi s desne Ocu. I opet će doći u slavi suditi žive i mrtve, i njegovu kraljevstvu neće biti kraja. I u Duha Svetoga, Gospodina i životvorca; koji izlazi od Oca i Sina. Koji se s Ocem i Sinom skupa časti i zajedno slavi; koji je govorio po prorocima. I u jednu svetu katoličku i apostolsku Crkvu. Ispovijedam jedno krštenje za oproštenje grijeha. I iščekujem uskrsnuće mrtvih. I život budućega vijeka. Amen."},"built":"2026-11-16","coverage":{"masses":4147,"blocks":47159,"site":46870,"siteVariant":1319,"kniewald":0,"missing":289,"unique":6142,"uniqueSite":6100,"uniqueKniewald":0,"uniqueMissing":42},"hasZagreb":false});
